```python
class FuzzyDict(dict):
    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self._keys_lower = {k.lower(): k for k in self.keys()}

    def __setitem__(self, k, v) -> None:
        super().__setitem__(k, v)
        self._keys_lower[k.lower()] = k

    def __getitem__(self, key):
        try:
            return super().__getitem__(key)
        except KeyError as error:
            # Check for a near match
            best_matches = self.get_best_matches(key)
            if len(best_matches) == 1:
                if isinstance(best_matches[0], str):
                    pybamm.logger.warning(
                        f"'{key}' not found. Using '{best_matches[0]}' instead."
                    )
                    return super().__getitem__(best_matches[0])
            raise error

    def get_best_matches(self, key: str) -> list:
        """
        Search keys for a fuzzy match to the given key.
        Return a list of best matches, with the best match first.
        If there are multiple equally good matches, return all of them.
        """
        # First check for a case-insensitive match
        key = key.lower()
        if key in self._keys_lower:
            return [self._keys_lower[key]]
        # Find all the keys that contain the search term (case-insensitive)
        best_matches = []
        for k, v in self._keys_lower.items():
            if key in v:
                best_matches.append(v)
        if best_matches:
            return best_matches
        # Otherwise, use difflib to find the closest matches
        return difflib.get_close_matches(key, self._keys_lower.keys(), n=3, cutoff=0.75)
```

