from marshmallow import Schema

from .common import resolve_schema_cls, resolve_schema_instance


class SchemaResolver:
    def __init__(self, converter):
        self.converter = converter

    def resolve_schema_in_parameters(self, parameters):
        """Resolve schema in the parameters of an operation object.

        See https://github.com/OAI/OpenAPI-Specification/blob/master/versions/3.0.2.md#parameterObject
        """
        for parameter in parameters:
            if "schema" in parameter:
                parameter["schema"] = self.resolve_schema_dict(parameter["schema"])

    def resolve_schema_in_request_body(self, request_body):
        """Resolve schema in the request body of an operation object.

        See https://github.com/OAI/OpenAPI-Specification/blob/master/versions/3.0.2.md#requestBodyObject
        """
        if "schema" in request_body:
